import { createPath, parsePath } from "react-router-dom";

export const previewHome = "/landing-preview";

// These are the public destinations served by the existing application's Static pages.
// Keep each page's own search parameters available to its filters and calculators.
export const publicPreviewPages = [
  { path: "/lender", screen: "LenderPage", art: "capital", aliases: ["lenders", "why-lend", "why-lend-at-oxyloans"] },
  { path: "/borrower", screen: "BorrowerPage", art: "document", aliases: ["borrowers", "why-borrow", "why-borrow-at-oxyloans"] },
  { path: "/how-it-works", screen: "HowItWorks", art: "network", aliases: ["howitworks"] },
  { path: "/faqs", screen: "FAQPage", art: "document", aliases: ["faq", "lender-faq", "lender-faqs", "borrower-faq", "borrower-faqs"] },
  { path: "/contact-us", screen: "ContactUs", art: "network", aliases: ["contact", "contactus"] },
  { path: "/team-management", screen: "TeamManagement", art: "network", aliases: ["team", "management", "our-team"] },
  { path: "/advisory-team", screen: "AdvisoryBoard", art: "network", aliases: ["advisory", "advisory-board", "our-advisory-team"] },
  { path: "/blogs", screen: "BlogPage", art: "network", aliases: ["blog"] },
  { path: "/blog/:slug", screen: "BlogPage", art: "network" },
  { path: "/personal-loans", screen: "PersonalLoan", art: "document", aliases: ["personalloans", "personal-loan", "personalloan"] },
  { path: "/sme-loans", screen: "SMELoan", art: "capital", aliases: ["smeloans", "sme-loan", "smeloan"] },
  { path: "/business-loans", screen: "InternationalBusinessExpansion", art: "capital", aliases: ["businessloans", "business-loan", "businessloan"] },
  { path: "/international-business-expansion-loans", screen: "InternationalBusinessExpansion", art: "capital", aliases: ["international-business-expansion", "international-business-loans"] },
  { path: "/motor-loans", screen: "MotorLoan", art: "document", aliases: ["motorloans", "motor-loan", "motorloan"] },
  { path: "/travel-loans", screen: "TravelLoan", art: "document", aliases: ["travelloans", "travel-loan", "travelloan"] },
  { path: "/emicalculator", screen: "LoanEmiCalculator", art: "capital", aliases: ["emi-calculator", "loan-emi-calculator", "calculator"] },
  { path: "/loan-performance", screen: "LoanPerformance", art: "capital", aliases: ["loanperformance", "loan-performance-details"] },
  { path: "/know-your-earnings", screen: "KnowYourEarnings", art: "capital", aliases: ["knowyourearnings", "know-my-earnings"] },
  { path: "/know-your-fees", screen: "KnowYourFees", art: "document", aliases: ["knowyourfees", "know-your-fee", "knowyourfee"] },
  { path: "/know-your-tax", screen: "KnowYourTax", art: "document", aliases: ["knowyourtax"] },
  { path: "/latest-egm-notice", screen: "LatestEGMNotice", art: "document", aliases: ["latestegmnotice", "latest-egm", "latestegm", "egm-notice"] },
  { path: "/rbi-directions", screen: "RBIDirections", art: "document", aliases: ["rbidirections"] },
  { path: "/transparency", screen: "TransparencyDisclosures", art: "network", aliases: ["transparency-and-disclosure-requirements", "transparency-and-disclosures"] },
  { path: "/grievance-redressal-mechanism", screen: "GrievanceRedressal", art: "document", aliases: ["grievances-redressal-mechanism", "grievance-redressal", "grievances-redressal", "grievance", "grievances"] },
  { path: "/privacy-policy", screen: "PrivacyPolicy", art: "document", aliases: ["privacypolicy"] },
  { path: "/terms", screen: "TermsPreview", art: "document" },
];

const publicPaths = new Map();
for (const { path, aliases = [] } of publicPreviewPages) {
  const view = path.slice(1);
  publicPaths.set(path, view);
  for (const alias of aliases) publicPaths.set("/" + alias, view);
}

const homeFragments = { "#about-section": "#about-us", "#success-stories": "#testimonials" };

export function publicPreviewHref(to) {
  const destination = typeof to === "string" ? parsePath(to) : to;
  const pathname = (destination.pathname || "").replace(/\/$/, "");
  const { search = "", hash = "" } = destination;
  if (["/landing", "/landing-old", "/home"].includes(pathname)) {
    return previewHome + (homeFragments[hash] || hash);
  }

  const params = new URLSearchParams(search);
  let view = publicPaths.get(pathname.toLowerCase());
  const blogPage = pathname.match(/^\/blog\/page\/(\d+)$/i);
  if (blogPage) {
    view = "blogs";
    params.set("page", blogPage[1]);
  } else if (/^\/blog\/[^/]+$/i.test(pathname)) {
    view = pathname.slice(1);
  }
  if (!view) return typeof to === "string" ? to : createPath(to);

  const category = pathname.match(/^\/(lender|borrower)-faqs?$/i);
  if (category && !params.has("category")) params.set("category", category[1].toLowerCase());
  params.delete("view");
  const query = new URLSearchParams({ view });
  params.forEach((value, key) => query.append(key, value));
  return previewHome + "?" + query.toString() + hash;
}

/** The real browser URL carries the preview; a reused page sees its ordinary URL. */
export function publicPageLocation(location) {
  const params = new URLSearchParams(location.search);
  const view = params.get("view");
  if (!view) return null;
  params.delete("view");
  const query = params.toString();
  return { ...location, pathname: "/" + view, search: query ? "?" + query : "" };
}
