import React, { useEffect, useRef, useState } from "react";
import { processSteps } from "./previewProcessSteps";
import { Link } from "react-router-dom";
import { FaArrowRight, FaCheckCircle, FaCoins, FaFileInvoice, FaHandshake, FaSlidersH, FaUser, FaUsers } from "react-icons/fa";
import logo from "../../../assets/img/oxylogodashboard.png";
import "./PreviewLendingProcess.css";

const tiles = [
  ["lender-partner", FaUsers, "Lender–Borrower Partner", "Connect with verified lenders and borrowers."],
  ["borrower-main", FaUser, "Borrowers", "Explore loans for personal or business needs."],
  ["lender-reviews", FaCoins, "Discover Loans & Returns", "Review loan opportunities and potential returns."],
  ["borrower-apply", FaFileInvoice, "Submit Loan Application", "Apply online and submit your loan request."],
  ["lender-negotiate", FaHandshake, "Negotiation & Terms", "Agree on a loan amount, rate and repayment term."],
  ["borrower-offers", FaSlidersH, "Select the Best Offer", "Compare loan offers and choose one that fits."],
];

const sequence = Object.keys(processSteps);
const intervalMs = 10000;

export default function PreviewLendingProcess({ reducedMotion }) {
  const [active, setActive] = useState("overview");
  const [hovered, setHovered] = useState(false);
  const [keyboardFocus, setKeyboardFocus] = useState(false);
  const [paused, setPaused] = useState(false);
  const [visible, setVisible] = useState(false);
  const section = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting));
    observer.observe(section.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!visible || paused || hovered || keyboardFocus || reducedMotion) return;
    const timer = window.setTimeout(() => {
      setActive(sequence[(sequence.indexOf(active) + 1) % sequence.length]);
    }, intervalMs);
    return () => window.clearTimeout(timer);
  }, [active, visible, paused, hovered, keyboardFocus, reducedMotion]);

  function tileProps(id) {
    return {
      type: "button",
      "aria-pressed": active === id,
      "aria-controls": "oxy-process-details",
      onPointerEnter: event => { if (event.pointerType === "mouse") setActive(id); },
      onFocus: event => { if (event.target.matches(":focus-visible")) setActive(id); },
      onClick: event => {
        setActive(id);
        if (!event.currentTarget.matches(":focus-visible") && !window.matchMedia("(hover: hover)").matches) setPaused(true);
      },
    };
  }

  return (
    <section ref={section} data-preview-loop=""
      onPointerEnter={event => { if (event.pointerType === "mouse") setHovered(true); }}
      onPointerLeave={() => setHovered(false)}
      onFocusCapture={event => setKeyboardFocus(event.target.matches(":focus-visible"))}
      onKeyDownCapture={() => setKeyboardFocus(true)}
      onBlurCapture={event => { if (!event.currentTarget.contains(event.relatedTarget)) setKeyboardFocus(false); }}
      className="oxy-process-preview" aria-labelledby="oxy-process-preview-heading" id="proven-process">
      <div className="oxy-preview-container">
        <h2 id="oxy-process-preview-heading">Proven process <em>produces results</em></h2>
        <div className="oxy-process-preview-divider" aria-hidden="true">○</div>
        <div className="oxy-process-preview-layout">
          <div className="oxy-process-preview-comb" role="group" aria-label="Choose a process step">
            {tiles.map(([id, Icon, title, description]) => (
              <button className="oxy-process-preview-cell" key={id} {...tileProps(id)}>
                <span className="oxy-process-preview-face">
                  <Icon aria-hidden="true" />
                  <strong>{title}</strong>
                  <span>{description}</span>
                </span>
              </button>
            ))}
            <button className="oxy-process-preview-cell oxy-process-preview-brand" {...tileProps("overview")} aria-label="P2P lending overview">
              <span className="oxy-process-preview-face"><img src={logo} alt="OxyLoans" /><strong>P2P Lending</strong></span>
            </button>
          </div>
          <div className="oxy-process-preview-copy" id="oxy-process-details">
            <div className="oxy-process-preview-controls">
              <span>Step {sequence.indexOf(active) + 1} of {sequence.length}</span>
              {!reducedMotion && <button type="button" onClick={() => setPaused(value => !value)}>
                {paused ? "Resume slideshow" : "Pause slideshow"}
              </button>}
            </div>
            <div className="oxy-process-preview-panels" aria-live={keyboardFocus || paused ? "polite" : "off"}>
              {sequence.map(id => {
                const step = processSteps[id];
                return (
                  <div key={id} className="oxy-process-preview-panel" aria-hidden={active !== id}>
                    <span className="oxy-process-preview-badge">{step.category}</span>
                    <h3>{step.title}</h3>
                    <p className="oxy-process-preview-intro">{step.subtitle}</p>
                    <p>{step.description}</p>
                    <ul>{step.points.map(item => <li key={item}><FaCheckCircle aria-hidden="true" />{item}</li>)}</ul>
                  </div>
                );
              })}
            </div>
            <div className="oxy-process-preview-actions">
              <Link to="/register">Start lending <FaArrowRight aria-hidden="true" /></Link>
              <Link to="/borrower_register">Start borrowing <FaArrowRight aria-hidden="true" /></Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
