import React, { useState } from "react";
import { Link } from "react-router-dom";
import { FaArrowRight, FaChevronDown } from "react-icons/fa";
import { publicPreviewHref } from "./publicPreviewPaths";

export default function PreviewFAQGroup({ category, title, icon: Icon, questions }) {
  const [open, setOpen] = useState(null);
  return (
    <section className={`oxy-faq-box ${category === "borrower" ? "lavender-box" : ""}`} aria-labelledby={`oxy-faq-${category}`} data-preview-reveal="">
      <div className="oxy-faq-box-header">
        <Icon className="oxy-faq-box-icon" aria-hidden="true" />
        <h3 className="oxy-faq-box-title" id={`oxy-faq-${category}`}>{title}</h3>
      </div>
      <div className="oxy-accordion-list">
        {questions.map(({ question, answer }, index) => {
          const expanded = index === open;
          const id = `oxy-${category}-answer-${index}`;
          return (
            <div className={`oxy-accordion-item ${expanded ? "is-open" : ""}`} key={question}>
              <button type="button" className="oxy-accordion-trigger" aria-expanded={expanded}
                aria-controls={id} onClick={() => setOpen(expanded ? null : index)}>
                <span>{question}</span><FaChevronDown aria-hidden="true" />
              </button>
              <div id={id} className="oxy-film-answer" aria-hidden={!expanded}>
                <div><p className="oxy-accordion-content">{answer}</p></div>
              </div>
            </div>
          );
        })}
      </div>
      <Link to={publicPreviewHref(`/faqs?category=${category}`)} className="oxy-faq-footer-link">
        View all {category} FAQs <FaArrowRight aria-hidden="true" />
      </Link>
    </section>
  );
}
