import React, { useId } from "react";

// A shallow fan of contours follows the same curve as the filled ribbon.
function strand(t) {
  return `M-100 ${440 + t * 134} C210 ${766 - t * 70}, 530 ${384 + t * 96}, 790 ${494 + t * 82} S1190 ${836 - t * 144}, 1540 ${247 + t * 132}`;
}
const contours = Array.from({ length: 22 }, (_, i) => strand(i / 21));

export default function PreviewLightField() {
  const id = useId().replace(/:/g, "");
  return (
    <svg className="oxy-film-field" viewBox="0 0 1440 660" preserveAspectRatio="none" aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={id + "-silk"} x2=".2" y2="1">
          <stop stopColor="#93dd91" stopOpacity=".3" />
          <stop offset=".26" stopColor="#64ac71" stopOpacity=".12" />
          <stop offset="1" stopColor="#052d22" stopOpacity=".04" />
        </linearGradient>
        <linearGradient id={id + "-edge"}>
          <stop stopColor="#92efaa" stopOpacity=".28" />
          <stop offset=".4" stopColor="#579978" stopOpacity=".10" />
          <stop offset=".8" stopColor="#bdf779" stopOpacity=".75" />
          <stop offset="1" stopColor="#66bf99" stopOpacity=".18" />
        </linearGradient>
      </defs>
      <g className="oxy-film-strands">
        <path d={strand(0) + " L1540 760 H-100Z"} fill={`url(#${id}-silk)`} />
        <g fill="none" stroke={`url(#${id}-edge)`} strokeWidth=".85">
          {contours.map(d => <path key={d} d={d} />)}
        </g>
      </g>
    </svg>
  );
}
