import React, { useEffect, useRef } from "react";
import { FaCoins, FaUsers, FaShieldAlt } from "react-icons/fa";

const figures = [
  { label: "Disbursal", total: 7000, suffix: "+ Crores", icon: FaCoins },
  { label: "Borrowers", total: 300000, suffix: "+", icon: FaUsers },
  { label: "Lenders", total: 50000, suffix: "+", icon: FaShieldAlt },
];
const format = new Intl.NumberFormat("en-IN");

export default function PreviewMetrics({ reducedMotion }) {
  const band = useRef(null);
  useEffect(() => {
    if (reducedMotion || !window.IntersectionObserver) return;
    const values = band.current.querySelectorAll("[data-count]");
    let frame = 0;
    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      observer.disconnect();
      const start = performance.now();
      function count(now) {
        const elapsed = now - start;
        figures.forEach(({ total }, index) => {
          const t = Math.max(0, Math.min(1, (elapsed - index * 85) / 1050));
          values[index].textContent = format.format(Math.round(total * (1 - (1 - t) ** 3)));
        });
        if (elapsed < 1220) frame = requestAnimationFrame(count);
      }
      frame = requestAnimationFrame(count);
    }, { threshold: 0.25 });
    observer.observe(band.current);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      figures.forEach(({ total }, index) => { values[index].textContent = format.format(total); });
    };
  }, [reducedMotion]);
  return (
    <section className="oxy-metrics-bar" ref={band} aria-label="OxyLoans platform figures">
      <dl className="oxy-preview-container oxy-metrics-grid">
        {figures.map(({ label, total, suffix, icon: Icon }, index) => (
          <div key={label} className="oxy-metric-col" data-preview-reveal="" style={{ "--entry-delay": index * 70 + "ms" }}>
            <dt className="oxy-metric-label"><Icon aria-hidden="true" />{label}</dt>
            <dd className="oxy-metric-value">
              <span className="oxy-film-sr">{format.format(total)}{suffix}</span>
              <span aria-hidden="true"><span data-count="">{format.format(total)}</span>{suffix}</span>
            </dd>
          </div>
        ))}
      </dl>
    </section>
  );
}
